#include "mediaengine/avbreader.h"
#include "mediaengine/avbreferences.h"
#include "mediaengine/avbobjects_p.h"
#include <QCoreApplication>
#include <QCryptographicHash>
#include <QElapsedTimer>
#include <QFile>
#include <QJsonArray>
#include <QJsonDocument>
#include <QJsonObject>
#include <QSet>
#include <QTextStream>
#include <algorithm>
#include <chrono>
#include <condition_variable>
#include <mutex>
#include <thread>

using namespace MediaEngine;

QString issueKind(AvbResolutionIssue::Kind kind)
{
	switch (kind)
	{
	case AvbResolutionIssue::Kind::InvalidSelection: return QStringLiteral("InvalidSelection");
	case AvbResolutionIssue::Kind::IncompleteSource: return QStringLiteral("IncompleteSource");
	case AvbResolutionIssue::Kind::UnresolvedReference: return QStringLiteral("UnresolvedReference");
	case AvbResolutionIssue::Kind::AmbiguousReference: return QStringLiteral("AmbiguousReference");
	case AvbResolutionIssue::Kind::UnsupportedIdentity: return QStringLiteral("UnsupportedIdentity");
	case AvbResolutionIssue::Kind::Cancelled: return QStringLiteral("Cancelled");
	}
	return QStringLiteral("Unknown");
}

int main(int argc, char **argv)
{
	QCoreApplication app(argc, argv);
	if (argc != 2)
		return 2;
	QFile file(QString::fromLocal8Bit(argv[1]));
	if (!file.open(QIODevice::ReadOnly))
		return 3;
	Cancellation parseCancellation;
	QElapsedTimer timer;
	timer.start();
	auto source = QSharedPointer<ParsedSource>::create(AvbReader{}.read(file, {{}, parseCancellation}));
	const auto parseMilliseconds = timer.elapsed();
	Cancellation cancellation;
	AvbReferenceIndex index(source, cancellation);
	QVector<ObjectHandle> chosen;
	QJsonArray matchingSequences;
	for (const auto &entry : index.sequences())
		if (entry.name == QLatin1String("HAA_1729_8645_SUBMASTER.Exported.01"))
		{
			chosen.append(entry.objectHandle);
			matchingSequences.append(QJsonObject{{"object", qint64(entry.objectHandle)}, {"name", entry.name}});
		}
	if (chosen.size() != 1)
	{
		QTextStream(stdout) << QJsonDocument(QJsonObject{{"error", "Expected exactly one listed matching sequence"},
			{"matchingSequences", matchingSequences}, {"readerOutcome", int(source->outcome)}}).toJson(QJsonDocument::Compact);
		return 4;
	}
	std::mutex mutex;
	std::condition_variable finished;
	bool complete = false;
	std::thread watchdog([&]
	{
		std::unique_lock<std::mutex> lock(mutex);
		if (!finished.wait_for(lock, std::chrono::seconds(30), [&] { return complete; }))
			cancellation.cancel();
	});
	timer.restart();
	const auto result = index.resolveReferences({AvbSelection::Kind::SelectedSequences, chosen}, cancellation);
	const auto resolveMilliseconds = timer.elapsed();
	{
		std::lock_guard<std::mutex> lock(mutex);
		complete = true;
	}
	finished.notify_one();
	watchdog.join();
	QSet<QByteArray> uniqueIds;
	QSet<QByteArray> legacyIds;
	for (const auto &reference : result.mediaReferences)
	{
		if (!reference.fileMobId.isEmpty()) uniqueIds.insert(reference.fileMobId);
		if (!reference.legacyId.isEmpty()) legacyIds.insert(reference.legacyId);
	}
	QList<QByteArray> sortedIds = uniqueIds.values();
	std::sort(sortedIds.begin(), sortedIds.end());
	QCryptographicHash idHash(QCryptographicHash::Sha256);
	QJsonArray samples;
	for (const auto &id : sortedIds)
	{
		idHash.addData(id);
		if (samples.size() < 4) samples.append(QString::fromLatin1(id.toHex()));
	}
	QJsonObject counts;
	QJsonObject classCounts;
	QJsonObject explanationCounts;
	QHash<ObjectHandle, const AvidObject *> objects;
	QHash<ObjectHandle, QVector<const Relationship *>> outgoing;
	for (const auto &object : source->objects) objects.insert(object.handle, &object);
	for (const auto &edge : source->relationships) outgoing[edge.origin].append(&edge);
	QJsonArray examples;
	QSet<ObjectHandle> sideIssueObjects;
	for (const auto &issue : result.issues)
	{
		const auto name = issueKind(issue.kind);
		counts[name] = counts.value(name).toInt() + 1;
		const auto *object = objects.value(issue.objectHandle);
		const auto className = object && object->avb ? QString::fromLatin1(object->avb->classId) : QStringLiteral("Unavailable");
		classCounts[className] = classCounts.value(className).toInt() + 1;
		explanationCounts[issue.explanation] = explanationCounts.value(issue.explanation).toInt() + 1;
		if (issue.explanation.startsWith(QLatin1String("A recorded side reference"))) sideIssueObjects.insert(issue.objectHandle);
		if (examples.size() < 12)
			examples.append(QJsonObject{{"kind", name}, {"object", qint64(issue.objectHandle)},
				{"objectClass", className}, {"field", issue.propertyLocator.name}, {"explanation", issue.explanation}});
	}
	QJsonObject sideLinkCounts;
	QJsonArray sideLinkExamples;
	auto sortedSideIssueObjects = sideIssueObjects.values();
	std::sort(sortedSideIssueObjects.begin(), sortedSideIssueObjects.end());
	for (const auto handle : sortedSideIssueObjects)
		for (const auto *edge : outgoing.value(handle))
		{
			const auto *child = objects.value(edge->target);
			if (!child || !child->avb || !Detail::supportsAvbComponent(child->avb->classId)) continue;
			const auto &field = edge->locator.name;
			if (field.startsWith(QLatin1String("Sequence.components[")) ||
				(field.startsWith(QLatin1String("TrackGroup.tracks[")) && field.endsWith(QLatin1String(".component"))) ||
				field == QLatin1String("Component.precomputed") || field == QLatin1String("SourceClip.mob_id") ||
				field == QLatin1String("AudioSuitePluginEffect.mob_id")) continue;
			const auto *origin = objects.value(handle);
			const auto originClass = origin && origin->avb ? QString::fromLatin1(origin->avb->classId) : QStringLiteral("Unavailable");
			const auto childClass = QString::fromLatin1(child->avb->classId);
			const auto key = originClass + QLatin1Char(':') + field + QStringLiteral("->") + childClass;
			sideLinkCounts[key] = sideLinkCounts.value(key).toInt() + 1;
			if (sideLinkExamples.size() < 10)
			{
				qsizetype nonNullOutgoing = 0;
				QJsonArray outgoingFields;
				for (const auto *next : outgoing.value(child->handle))
					if (next->target || (next->referenceEncoding == QLatin1String("AVB.MobId.MaterialLE") && !next->recordedReference.toByteArray().isEmpty()))
					{
						++nonNullOutgoing;
						if (outgoingFields.size() < 8) outgoingFields.append(next->locator.name);
					}
				sideLinkExamples.append(QJsonObject{{"object", qint64(handle)}, {"objectClass", originClass}, {"field", field},
					{"target", qint64(child->handle)}, {"targetClass", childClass}, {"targetNonNullOutgoing", nonNullOutgoing},
					{"targetOutgoingFields", outgoingFields}});
			}
		}
	bool reached = false;
	bool selected = false;
	bool unusedA = false;
	bool unusedB = false;
	for (const auto &edge : result.edges)
	{
		reached |= edge.origin == 33511 || edge.target == 33511;
		selected |= edge.origin == 33511 && edge.target == 11236;
		unusedA |= edge.origin == 33511 && edge.target == 11237;
		unusedB |= edge.origin == 33511 && edge.target == 11238;
	}
	QJsonArray diagnostics;
	for (const auto &diagnostic : source->diagnostics.mid(0, 6)) diagnostics.append(diagnostic);
	const QJsonObject output{{"matchingSequences", matchingSequences}, {"readerOutcome", int(source->outcome)},
		{"readerComplete", source->outcome == ParsedSource::Outcome::Complete}, {"readerDiagnostics", diagnostics},
		{"parsedObjects", source->objects.size()}, {"parsedRelationships", source->relationships.size()},
		{"parseMilliseconds", parseMilliseconds}, {"resolveMilliseconds", resolveMilliseconds},
		{"resolveDeadlineSeconds", 30}, {"coverageComplete", result.coverageComplete}, {"cancelled", result.cancelled},
		{"resolvedEdges", result.edges.size()}, {"mediaReferenceOccurrences", result.mediaReferences.size()},
		{"uniqueFullFileMobIds", uniqueIds.size()}, {"uniqueLegacyIds", legacyIds.size()},
		{"fullIdSetSha256", QString::fromLatin1(idHash.result().toHex())}, {"sampleFullIds", samples},
		{"issueCount", result.issues.size()}, {"issueKinds", counts}, {"issueExamples", examples},
		{"issueObjectClassCounts", classCounts}, {"issueExplanationCounts", explanationCounts},
		{"sideLinkCandidateCounts", sideLinkCounts}, {"sideLinkExamples", sideLinkExamples},
		{"selectorCheck", QJsonObject{{"object", 33511}, {"reachedByResolvedEdge", reached},
			{"selectedEdge33511To11236", selected}, {"unselectedEdge33511To11237", unusedA},
			{"unselectedEdge33511To11238", unusedB},
			{"selectedEdgeCheckApplies", reached}, {"selectedEdgeObservedAndAlternativesAbsent", reached && selected && !unusedA && !unusedB}}}};
	QTextStream(stdout) << QJsonDocument(output).toJson(QJsonDocument::Compact);
	return 0;
}
